-- 247: Original BrillaPrep BECE gap beta questions, subj_bece_science, part 3.
-- Curriculum-blueprint-aligned practice; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _expected_247 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _expected_247;
INSERT INTO _expected_247(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_science_agric_b001_021','topic_bece_science_agric','subj_bece_science','exam_bece','A newly purchased goat coughs during its separate observation period. What is the best next action?','multiple_choice','["A. Move it into the herd so all animals are exposed together","B. Keep it separated and obtain an animal-health assessment before herd contact","C. End observation because it has already been purchased","D. Crowd it with young animals to keep it warm"]','B','Continuing separation while the symptom is assessed reduces the chance of introducing an infectious disease and allows treatment or testing before herd contact. Therefore the correct answer is B: Keep it separated and obtain an animal-health assessment before herd contact.','hard',1,1,90,'Explain','AO3'),
  ('q_bece_science_agric_b001_022','topic_bece_science_agric','subj_bece_science','exam_bece','What is the purpose of vaccination in farm animals?','multiple_choice','["A. To cure every existing injury","B. To replace clean water","C. To eliminate all management","D. To stimulate specific immunity before likely exposure"]','D','Vaccines prepare the immune system to respond more effectively to particular pathogens, but hygiene and biosecurity remain necessary. Therefore the correct answer is D: To stimulate specific immunity before likely exposure.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_023','topic_bece_science_agric','subj_bece_science','exam_bece','Which animal is a ruminant?','multiple_choice','["A. A chicken","B. A pig","C. A goat","D. A tilapia"]','C','Goats are ruminants with specialised stomach compartments that support microbial digestion and rumination of fibrous feed. Therefore the correct answer is C: A goat.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_science_agric_b001_024','topic_bece_science_agric','subj_bece_science','exam_bece','Why keep breeding and birth records for livestock?','multiple_choice','["A. To guarantee identical offspring","B. To avoid animal identification","C. To replace observation","D. To track performance, parentage and health events"]','D','Reliable records support selection, expected birth dates, health follow-up and evaluation of reproductive performance. Therefore the correct answer is D: To track performance, parentage and health events.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_025','topic_bece_science_agric','subj_bece_science','exam_bece','How does drying preserve food?','multiple_choice','["A. It removes water needed by many spoilage organisms","B. It adds unlimited moisture","C. It makes food sterile forever","D. It increases enzyme activity without limit"]','A','Lower water availability slows microbial growth and many chemical changes, although dried food still needs clean protected storage. Therefore the correct answer is A: It removes water needed by many spoilage organisms.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_026','topic_bece_science_agric','subj_bece_science','exam_bece','Why can salting help preserve fish?','multiple_choice','["A. It supplies oxygen to bacteria","B. It lowers available water and inhibits many microorganisms","C. It guarantees no contamination","D. It converts fish into grain"]','B','A sufficiently salty environment draws water from tissues and microbes, slowing growth when combined with hygienic handling. Therefore the correct answer is B: It lowers available water and inhibits many microorganisms.','hard',1,1,90,'Explain','AO3'),
  ('q_bece_science_agric_b001_027','topic_bece_science_agric','subj_bece_science','exam_bece','How does refrigeration slow food spoilage?','multiple_choice','["A. It removes every microbe instantly","B. It adds sunlight","C. Low temperature reduces microbial growth and reaction rates","D. It raises food temperature"]','C','Cooling slows microbial multiplication and enzyme activity but does not sterilise food, so safe handling and time limits still matter. Therefore the correct answer is C: Low temperature reduces microbial growth and reaction rates.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_028','topic_bece_science_agric','subj_bece_science','exam_bece','What is pasteurisation intended to do?','multiple_choice','["A. Burn food to ash","B. Reduce harmful microorganisms using controlled heating","C. Freeze food permanently","D. Add soil organisms"]','B','Pasteurisation applies a defined time and temperature to reduce pathogens and spoilage organisms while limiting quality damage. Therefore the correct answer is B: Reduce harmful microorganisms using controlled heating.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_029','topic_bece_science_agric','subj_bece_science','exam_bece','Why wash hands before handling harvested food?','multiple_choice','["A. To make food heavier","B. To replace clean equipment","C. To reduce transfer of dirt and harmful microorganisms","D. To increase contamination"]','C','Clean hands reduce cross-contamination from soil, animals, waste and other sources during preparation, packing or storage. Therefore the correct answer is C: To reduce transfer of dirt and harmful microorganisms.','medium',1,1,90,'Apply','AO2'),
  ('q_bece_science_agric_b001_030','topic_bece_science_agric','subj_bece_science','exam_bece','Why should bruised fruits be separated during storage?','multiple_choice','["A. Damage speeds spoilage and can affect nearby produce","B. Bruising always improves quality","C. Damaged fruit stops respiration","D. It becomes permanently sterile"]','A','Broken tissues lose water and are more open to microorganisms, so sorting reduces spread and protects sound produce. Therefore the correct answer is A: Damage speeds spoilage and can affect nearby produce.','medium',1,1,90,'Explain','AO2');
CREATE TABLE IF NOT EXISTS _migration_247_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_247_guard;
INSERT INTO _migration_247_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM _expected_247) = 10
  AND NOT EXISTS (SELECT 1 FROM _expected_247 e LEFT JOIN topics t ON t.id=e.topic_id LEFT JOIN subjects s ON s.id=t.subject_id WHERE t.id IS NULL OR t.subject_id IS NOT e.subject_id OR s.exam_type_id IS NOT e.exam_type_id)
  AND NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_247 e ON e.question_id=q.id WHERE NOT (q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective))
  AND NOT EXISTS (SELECT 1 FROM question_content_releases r JOIN _expected_247 e ON e.question_id=r.question_id WHERE NOT (r.batch_id IS 'bece-science-agric-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1))
  AND NOT EXISTS (SELECT 1 FROM question_bank_remediation_log l JOIN _expected_247 e ON e.question_id=l.entity_id WHERE l.migration_id='247_bece_science_agric_beta_part_3' AND NOT (l.migration_id IS '247_bece_science_agric_beta_part_3' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-science-agric-beta-001'))
  AND (((SELECT COUNT(*) FROM questions q JOIN _expected_247 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_247 e ON e.question_id=r.question_id)=0 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_247 e ON e.question_id=l.entity_id WHERE l.migration_id='247_bece_science_agric_beta_part_3') IN (0,10))
    OR ((SELECT COUNT(*) FROM questions q JOIN _expected_247 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_247 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-science-agric-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_247 e ON e.question_id=l.entity_id WHERE l.migration_id IS '247_bece_science_agric_beta_part_3' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-science-agric-beta-001')=10))
THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) SELECT question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective FROM _expected_247;
INSERT OR IGNORE INTO question_content_releases (question_id,batch_id,quality_assurance,release_channel,content_label,source_url,official_exam_board_content,feedback_enabled) SELECT q.id,'bece-science-agric-beta-001','automated_beta','beta','Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.','https://nacca.gov.gh/common-core-programme-ccp/',0,1 FROM questions q JOIN _expected_247 e ON e.question_id=q.id;
INSERT OR IGNORE INTO question_bank_remediation_log (migration_id,entity_type,entity_id,field_name,old_value,new_value) SELECT '247_bece_science_agric_beta_part_3','question',q.id,'insert',NULL,'bece-science-agric-beta-001' FROM questions q JOIN _expected_247 e ON e.question_id=q.id;
INSERT INTO _migration_247_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM questions q JOIN _expected_247 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
  AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_247 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-science-agric-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10
  AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_247 e ON e.question_id=l.entity_id WHERE l.migration_id IS '247_bece_science_agric_beta_part_3' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-science-agric-beta-001')=10
  AND NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_247 e ON e.question_id=q.id JOIN questions other ON other.id IS NOT q.id AND lower(trim(other.question_text))=lower(trim(q.question_text)))
THEN 1 ELSE 0 END;
DROP TABLE _expected_247;
DROP TABLE _migration_247_guard;
